-- ---------------------------------------------------------------------
-- Düzenlenebilir dokümantasyon. Dokümanlar artık koddaki .md dosyaları değil, veritabanındaki kayıtlardır;
-- içerik site üzerindeki editörde (TipTap) yazılır ve ProseMirror JSON olarak saklanır.
-- Herkes düzenleyebilir: çalışanın değişikliği bir öneri (doc_revisions, BEKLIYOR) olur, yönetici onaylayınca dokümana
-- uygulanır. Yöneticinin kendi değişikliği doğrudan yayınlanır. Onaylanan öneriler sürüm geçmişidir.
-- base_version: öneri hangi sürüm üzerinde hazırlandı (arada doküman değiştiyse yönetici uyarılır).
-- ---------------------------------------------------------------------
CREATE TABLE docs (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(120) NOT NULL,
    title VARCHAR(200) NOT NULL,
    summary VARCHAR(500) NULL,
    category VARCHAR(40) NOT NULL,
    tags VARCHAR(300) NULL,
    content LONGTEXT NOT NULL,
    plain_text LONGTEXT NOT NULL,
    sort_order INT NOT NULL DEFAULT 99,
    version INT NOT NULL DEFAULT 1,
    created_by_id BIGINT NULL,
    updated_by_id BIGINT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_doc_slug UNIQUE (slug),
    CONSTRAINT fk_doc_created_by FOREIGN KEY (created_by_id) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT fk_doc_updated_by FOREIGN KEY (updated_by_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_doc_category (category, sort_order)
);

CREATE TABLE doc_revisions (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    doc_id BIGINT NULL,
    title VARCHAR(200) NOT NULL,
    summary VARCHAR(500) NULL,
    category VARCHAR(40) NOT NULL,
    tags VARCHAR(300) NULL,
    content LONGTEXT NOT NULL,
    base_version INT NULL,
    note VARCHAR(500) NULL,
    status ENUM('BEKLIYOR', 'ONAYLANDI', 'REDDEDILDI', 'GERI_CEKILDI') NOT NULL DEFAULT 'BEKLIYOR',
    author_id BIGINT NULL,
    decided_by_id BIGINT NULL,
    decision_note VARCHAR(500) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    decided_at TIMESTAMP NULL,
    CONSTRAINT fk_doc_rev_doc FOREIGN KEY (doc_id) REFERENCES docs(id) ON DELETE CASCADE,
    CONSTRAINT fk_doc_rev_author FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT fk_doc_rev_decided_by FOREIGN KEY (decided_by_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_doc_rev_status (status, created_at),
    INDEX idx_doc_rev_doc (doc_id, status)
);

-- Editörde eklenen görseller. Adres tahmin edilemeyen bir UUID'dir; <img> istekleri JWT taşımadığı için okuma herkese açıktır.
CREATE TABLE doc_images (
    id VARCHAR(36) PRIMARY KEY,
    content_type VARCHAR(40) NOT NULL,
    data LONGBLOB NOT NULL,
    size_bytes INT NOT NULL,
    uploaded_by_id BIGINT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_doc_image_user FOREIGN KEY (uploaded_by_id) REFERENCES users(id) ON DELETE SET NULL
);

ALTER TABLE action_logs
    MODIFY category ENUM('OTURUM', 'KULLANICI', 'PROFIL', 'PROJE', 'GOREV', 'IZIN', 'DUYURU', 'DOKUMAN', 'SISTEM') NOT NULL DEFAULT 'SISTEM';

ALTER TABLE notifications
    MODIFY type ENUM('TASK_ASSIGNED', 'TASK_DUE', 'TASK_COMPLETED', 'TASK_COMMENT', 'LEAVE_REQUESTED', 'LEAVE_DECIDED',
                     'LEAVE_REOPENED', 'PROJECT_ASSIGNED', 'STATUS_CHANGED', 'ANNOUNCEMENT', 'TODO_RECEIVED',
                     'PROFILE_REQUESTED', 'PROFILE_DECIDED', 'TODO_REMINDER', 'TODO_LIST_ADDED', 'TODO_COMMENT',
                     'DOC_REVISION_REQUESTED', 'DOC_REVISION_DECIDED') NOT NULL;

