wspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"container","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Docker konteyner adı; verilirse CPU/bellek toplanır"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"check","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"HTTP","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TCP","marks":[{"type":"code"}]},{"type":"text","text":" veya "},{"type":"text","text":"JDBC","marks":[{"type":"code"}]},{"type":"text","text":" sağlık kontrolü"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"target","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kontrol adresi (URL veya host:port)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"probe","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Servise özel metrikler: "},{"type":"text","text":"JVM","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MYSQL","marks":[{"type":"code"}]}]}]}]}]},{"type":"callout","attrs":{"kind":"IPUCU"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Compose projesine eklenen yeni konteynerler hiçbir ayar yapmadan sayfada \\"otomatik bulundu\\" etiketiyle listelenir. Anlamlı bir ad ve sağlık kontrolü için yine de "},{"type":"text","text":"monitoring.yml","marks":[{"type":"code"}]},{"type":"text","text":"''a eklemeniz önerilir."}]}]}]}',
        'Bir sorunu çözmek için önce onu görebilmemiz gerekir. Üç kaynağımız var: loglar, metrikler ve sağlık kontrolleri. Log seviyeleri Seviye Ne zaman Örnek ERROR Bir işlem başarısız oldu ve biri ilgilenmeli Veritabanına yazılamadı WARN Beklenmedik ama sistem devam ediyor Docker izleme vekiline ulaşılamadı INFO Önemli iş olayları Zamanlanmış izin işi 3 kaydı güncelledi DEBUG Geliştirme sırasında ayrıntı Gelen istek gövdesi Döngü içinde INFO log yazmayın. 10 saniyede bir çalışan bir iş, günde 8.640 satır üretir. İyi bir log satırı Log, bağlamı taşımalıdır; "hata oluştu" tek başına işe yaramaz: log.warn("İzin durumu güncellenemedi: userId={}, leaveId={}, neden={}", user.getId(), leave.getId(), e.getMessage()); Sistem İzleme sayfası Yöneticiler Sistem → Sistem İzleme sayfasından her servisin anlık durumunu görür: CPU ve bellek kullanımı (Docker istatistikleri) Sağlık kontrolü sonucu ve yanıt süresi Son bir saatin durum geçmişi ve grafikleri Servise özel metrikler: JVM heap, veritabanı bağlantı sayısı gibi Bir servis CPU veya bellek sınırının %85''ini aştığında ya da sağlık kontrolü yavaşladığında Uyarı, konteyner durduğunda veya kontrol başarısız olduğunda Çalışmıyor olarak görünür. Yeni bir servisi izlemeye ekleme Servisler monitoring.yml dosyasında tanımlanır. Yeni bir kayıt eklemek yeterlidir: - id: odeme-api name: Ödeme Sağlayıcısı kind: Dış servis check: HTTP target: https://status.example.com/health Alan Açıklama container Docker konteyner adı; verilirse CPU/bellek toplanır check HTTP, TCP veya JDBC sağlık kontrolü target Kontrol adresi (URL veya host:port) probe Servise özel metrikler: JVM, MYSQL Compose projesine eklenen yeni konteynerler hiçbir ayar yapmadan sayfada "otomatik bulundu" etiketiyle listelenir. Anlamlı bir ad ve sağlık kontrolü için yine de monitoring.yml''a eklemeniz önerilir.', 4, 1, (SELECT id FROM users WHERE full_name = 'Mustafa Koç' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Mustafa Koç' ORDER BY id LIMIT 1), '2026-09-29 06:00:00', '2026-09-29 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('guvenlik', 'Güvenlik Kontrol Listesi', 'Her pull request''te kontrol edilen güvenlik maddeleri, sır yönetimi ve OWASP Top 10''a karşı önlemler.', 'kalite', 'güvenlik,owasp,yetki',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Güvenlik bir ekibin değil herkesin işidir. Aşağıdaki liste her PR incelemesinde gözden geçirilir."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"PR kontrol listesi"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yeni uç noktada yetki kontrolü var mı? ("},{"type":"text","text":"requireAdmin","marks":[{"type":"code"}]},{"type":"text","text":" veya "},{"type":"text","text":"requireSelfOrAdmin","marks":[{"type":"code"}]},{"type":"text","text":")"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kullanıcı girdisi uzunluk ve biçim açısından doğrulanıyor mu?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hata mesajı iç ayrıntı (SQL, istisna metni) sızdırıyor mu?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loglara şifre, token veya kişisel veri yazılıyor mu?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yeni bağımlılık eklendiyse lisansı ve bilinen açıkları kontrol edildi mi?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Yetkilendirme"}]},{"type":"paragraph","content":[{"type":"text","text":"Her uç nokta varsayılan olarak kimlik doğrulama ister. Yetki kontrolü controller''ın ilk satırında yapılır:"}]},{"type":"codeBlock","attrs":{"language":"java"},"content":[{"type":"text","text":"@PutMapping(\\"/{id}\\")\\npublic ResponseEntity<TaskDto> update(@PathVariable Long id, @RequestBody Map<String, Object> body) {\\n    Task task = findTask(id);\\n    currentUser.requireSelfOrAdmin(task.getUser().getId(), \\"Yalnızca kendi görevlerinizi yönetebilirsiniz.\\");\\n    // ...\\n}"}]},{"type":"callout","attrs":{"kind":"UYARI"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Arayüzde bir butonu gizlemek yetki kontrolü değildir. Kural her zaman sunucuda uygulanır; arayüz yalnızca kullanıcıya yapamayacağı şeyi göstermez."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sır yönetimi"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Yapılır"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Yapılmaz"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sırları ortam değişkeniyle vermek"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sırları koda veya "},{"type":"text","text":"application.properties","marks":[{"type":"code"}]},{"type":"text","text":"''e yazmak"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Geliştirmede sahte değerler kullanmak"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Üretim şifresini yerel ortamda kullanmak"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sızan bir anahtarı hemen döndürmek"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Commit''i silip sorunun geçtiğini varsaymak"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"OWASP Top 10 karşısında"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Risk"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Önlemimiz"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Erişim kontrolü hataları"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Her uç noktada sunucu tarafı yetki kontrolü"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Enjeksiyon"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"JPA ve parametreli sorgular; elle birleştirilmiş SQL yok"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kimlik doğrulama hataları"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"BCrypt ile şifre özeti, güçlü şifre kuralı, pasif hesap anında kilitlenir"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Güvenlik yanlış yapılandırması"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"CORS yalnızca bilinen kaynaklara açık"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hassas veri ifşası"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hata mesajlarında iç ayrıntı yok"}]}]}]}]},{"type":"callout","attrs":{"kind":"ONEMLI"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bir güvenlik açığı fark ederseniz herkese açık kanala yazmayın; doğrudan takım liderine bildirin."}]}]}]}',
        'Güvenlik bir ekibin değil herkesin işidir. Aşağıdaki liste her PR incelemesinde gözden geçirilir. PR kontrol listesi Yeni uç noktada yetki kontrolü var mı? (requireAdmin veya requireSelfOrAdmin) Kullanıcı girdisi uzunluk ve biçim açısından doğrulanıyor mu? Hata mesajı iç ayrıntı (SQL, istisna metni) sızdırıyor mu? Loglara şifre, token veya kişisel veri yazılıyor mu? Yeni bağımlılık eklendiyse lisansı ve bilinen açıkları kontrol edildi mi? Yetkilendirme Her uç nokta varsayılan olarak kimlik doğrulama ister. Yetki kontrolü controller''ın ilk satırında yapılır: @PutMapping("/{id}") public ResponseEntity<TaskDto> update(@PathVariable Long id, @RequestBody Map<String, Object> body) { Task task = findTask(id); currentUser.requireSelfOrAdmin(task.getUser().getId(), "Yalnızca kendi görevlerinizi yönetebilirsiniz."); // ... } Arayüzde bir butonu gizlemek yetki kontrolü değildir. Kural her zaman sunucuda uygulanır; arayüz yalnızca kullanıcıya yapamayacağı şeyi göstermez. Sır yönetimi Yapılır Yapılmaz Sırları ortam değişkeniyle vermek Sırları koda veya application.properties''e yazmak Geliştirmede sahte değerler kullanmak Üretim şifresini yerel ortamda kullanmak Sızan bir anahtarı hemen döndürmek Commit''i silip sorunun geçtiğini varsaymak OWASP Top 10 karşısında Risk Önlemimiz Erişim kontrolü hataları Her uç noktada sunucu tarafı yetki kontrolü Enjeksiyon JPA ve parametreli sorgular; elle birleştirilmiş SQL yok Kimlik doğrulama hataları BCrypt ile şifre özeti, güçlü şifre kuralı, pasif hesap anında kilitlenir Güvenlik yanlış yapılandırması CORS yalnızca bilinen kaynaklara açık Hassas veri ifşası Hata mesajlarında iç ayrıntı yok Bir güvenlik açığı fark ederseniz herkese açık kanala yazmayın; doğrudan takım liderine bildirin.', 3, 1, (SELECT id FROM users WHERE full_name = 'Ali Yılmaz' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Ali Yılmaz' ORDER BY id LIMIT 1), '2026-09-03 06:00:00', '2026-09-03 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('hos-geldiniz', 'Mühendislik El Kitabına Hoş Geldiniz', 'Ekibin nasıl çalıştığını, hangi araçları kullandığını ve nereden başlamanız gerektiğini anlatan giriş rehberi.', 'baslarken', 'oryantasyon,ilk gün',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bu el kitabı, DevHub mühendislik ekibinin ortak hafızasıdır. Yeni katılan biri için ilk hafta okuma listesidir; ekipte uzun süredir olanlar için ise \\"bunu nasıl yapıyorduk?\\" sorusunun cevabıdır."}]},{"type":"callout","attrs":{"kind":"IPUCU"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Her sayfanın sağındaki "},{"type":"text","text":"Bu sayfada","marks":[{"type":"bold"}]},{"type":"text","text":" listesiyle bölümler arasında gezinebilir, "},{"type":"text","text":"Ctrl K","marks":[{"type":"code"}]},{"type":"text","text":" ile tüm dokümanlarda arama yapabilirsiniz."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Nasıl çalışıyoruz"}]},{"type":"paragraph","content":[{"type":"text","text":"Ekip iki haftalık sprintlerle çalışır. Her sprint pazartesi planlama ile başlar, ikinci haftanın cuma günü demo ve retrospektif ile biter. Günlük toplantılar 15 dakikayı geçmez ve saat 10:00''da yapılır."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sahiplik:","marks":[{"type":"bold"}]},{"type":"text","text":" Bir görevi alan kişi onu üretime kadar götürür; inceleme, test ve yayın dahil."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yazılı kültür:","marks":[{"type":"bold"}]},{"type":"text","text":" Kararlar toplantıda değil, dokümanda alınır. Toplantı yalnızca dokümanı tartışmak içindir."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Küçük adımlar:","marks":[{"type":"bold"}]},{"type":"text","text":" Büyük değişiklikler, her biri tek başına yayınlanabilecek küçük parçalara bölünür."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"İlk haftanız"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Geliştirme ortamınızı kurun: "},{"type":"text","text":"Geliştirme Ortamı Kurulumu","marks":[{"type":"link","attrs":{"href":"/docs/gelistirme-ortami"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Git akışımızı okuyun: "},{"type":"text","text":"Git Akışı ve Branch Stratejisi","marks":[{"type":"link","attrs":{"href":"/docs/git-akisi"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bir \\"iyi ilk görev\\" alın. Bu görevler panoda "},{"type":"text","text":"Düşük","marks":[{"type":"bold"}]},{"type":"text","text":" öncelikle ve "},{"type":"text","text":"ilk-gorev","marks":[{"type":"code"}]},{"type":"text","text":" etiketiyle işaretlidir."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"İlk pull request''inizi açın ve "},{"type":"text","text":"Kod İnceleme Rehberi","marks":[{"type":"link","attrs":{"href":"/docs/kod-inceleme"}}]},{"type":"text","text":"''ne göre inceleme isteyin."}]}]}],"attrs":{"start":1}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Kime sorarım?"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Konu"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kişi"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kanal"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Backend ve API"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ayşe Kaya"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"#backend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Mobil uygulama"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Zeynep Öztürk"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"#mobil"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Altyapı ve dağıtım"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Mustafa Koç"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"#altyapi"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ürün ve öncelikler"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Burak Polat"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"#urun"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tasarım sistemi"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Elif Arslan"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"#tasarim"}]}]}]}]},{"type":"callout","attrs":{"kind":"NOT"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bu el kitabı canlı bir dokümandır. Eksik ya da yanlış bir şey görürseniz düzeltmesini önermek sizin de işiniz."}]}]}]}',
        'Bu el kitabı, DevHub mühendislik ekibinin ortak hafızasıdır. Yeni katılan biri için ilk hafta okuma listesidir; ekipte uzun süredir olanlar için ise "bunu nasıl yapıyorduk?" sorusunun cevabıdır. Her sayfanın sağındaki Bu sayfada listesiyle bölümler arasında gezinebilir, Ctrl K ile tüm dokümanlarda arama yapabilirsiniz. Nasıl çalışıyoruz Ekip iki haftalık sprintlerle çalışır. Her sprint pazartesi planlama ile başlar, ikinci haftanın cuma günü demo ve retrospektif ile biter. Günlük toplantılar 15 dakikayı geçmez ve saat 10:00''da yapılır. Sahiplik: Bir görevi alan kişi onu üretime kadar götürür; inceleme, test ve yayın dahil. Yazılı kültür: Kararlar toplantıda değil, dokümanda alınır. Toplantı yalnızca dokümanı tartışmak içindir. Küçük adımlar: Büyük değişiklikler, her biri tek başına yayınlanabilecek küçük parçalara bölünür. İlk haftanız Geliştirme ortamınızı kurun: Geliştirme Ortamı Kurulumu Git akışımızı okuyun: Git Akışı ve Branch Stratejisi Bir "iyi ilk görev" alın. Bu görevler panoda Düşük öncelikle ve ilk-gorev etiketiyle işaretlidir. İlk pull request''inizi açın ve Kod İnceleme Rehberi''ne göre inceleme isteyin. Kime sorarım? Konu Kişi Kanal Backend ve API Ayşe Kaya #backend Mobil uygulama Zeynep Öztürk #mobil Altyapı ve dağıtım Mustafa Koç #altyapi Ürün ve öncelikler Burak Polat #urun Tasarım sistemi Elif Arslan #tasarim Bu el kitabı canlı bir dokümandır. Eksik ya da yanlış bir şey görürseniz düzeltmesini önermek sizin de işiniz.', 1, 1, (SELECT id FROM users WHERE full_name = 'Ali Yılmaz' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Ali Yılmaz' ORDER BY id LIMIT 1), '2026-09-18 06:00:00', '2026-09-18 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('kod-inceleme', 'Kod İnceleme Rehberi', 'İyi bir pull request nasıl hazırlanır, inceleyen neye bakar ve geri bildirim nasıl verilir.', 'surecler', 'code review,pull request',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kod incelemesinin amacı hata bulmaktan çok bilgiyi yaymaktır. İncelenen her PR, en az iki kişinin o kodu anladığı anlamına gelir."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Yazar olarak"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PR''ı küçük tutun. İnceleme kalitesi 400 satırdan sonra belirgin biçimde düşer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Açıklamaya ekran görüntüsü veya kısa bir video ekleyin; özellikle arayüz değişikliklerinde."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"İnceleme istemeden önce kendi diff''inizi baştan sona bir kez okuyun."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tartışmalı bir tasarım kararınız varsa kodun yanına yorum olarak "},{"type":"text","text":"neden","marks":[{"type":"bold"}]},{"type":"text","text":" o yolu seçtiğinizi yazın."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"İnceleyen olarak"}]},{"type":"paragraph","content":[{"type":"text","text":"İncelemeyi aşağıdaki sırayla yapın; en pahalı hatalar en üsttedir:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Doğruluk:","marks":[{"type":"bold"}]},{"type":"text","text":" Kod söylediği işi yapıyor mu? Sınır durumları (boş liste, null, hafta sonu, saat dilimi) düşünülmüş mü?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Güvenlik:","marks":[{"type":"bold"}]},{"type":"text","text":" Yetki kontrolü var mı? Kullanıcı girdisi doğrulanıyor mu?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tasarım:","marks":[{"type":"bold"}]},{"type":"text","text":" Değişiklik doğru katmanda mı? Var olan bir servis yeniden mi yazılmış?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test:","marks":[{"type":"bold"}]},{"type":"text","text":" Davranışı koruyan bir test eklenmiş mi?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Okunabilirlik:","marks":[{"type":"bold"}]},{"type":"text","text":" İsimler anlaşılır mı? Gereksiz karmaşıklık var mı?"}]}]}],"attrs":{"start":1}},{"type":"callout","attrs":{"kind":"NOT"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Biçimlendirme ve stil konuları incelemede tartışılmaz; bunlar lint ve formatlayıcının işidir."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Geri bildirim dili"}]},{"type":"paragraph","content":[{"type":"text","text":"Yorumun önüne etiket koyarak niyetinizi netleştirin:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Etiket"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Anlamı"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"engel:","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Birleştirmeden önce düzeltilmeli"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"öneri:","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Daha iyi olabilir, karar yazarın"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"soru:","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Anlamadım, açıklar mısın?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"ufak:","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Önemsiz, istersen düzelt"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"övgü:","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bunu beğendim"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Kişiyi değil kodu eleştirin. \\"Burada hata yapmışsın\\" yerine \\"Bu satır liste boşken hata veriyor gibi\\" deyin."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Süreler"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"İnceleme isteğine "},{"type":"text","text":"bir iş günü","marks":[{"type":"bold"}]},{"type":"text","text":" içinde ilk yanıt verilir."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yazar, geri bildirimlere en geç bir iş günü içinde döner."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Üç turdan uzun süren tartışmalar yazılı yazışma yerine 15 dakikalık bir görüşmeyle çözülür."}]}]}]}]}',
        'Kod incelemesinin amacı hata bulmaktan çok bilgiyi yaymaktır. İncelenen her PR, en az iki kişinin o kodu anladığı anlamına gelir. Yazar olarak PR''ı küçük tutun. İnceleme kalitesi 400 satırdan sonra belirgin biçimde düşer. Açıklamaya ekran görüntüsü veya kısa bir video ekleyin; özellikle arayüz değişikliklerinde. İnceleme istemeden önce kendi diff''inizi baştan sona bir kez okuyun. Tartışmalı bir tasarım kararınız varsa kodun yanına yorum olarak neden o yolu seçtiğinizi yazın. İnceleyen olarak İncelemeyi aşağıdaki sırayla yapın; en pahalı hatalar en üsttedir: Doğruluk: Kod söylediği işi yapıyor mu? Sınır durumları (boş liste, null, hafta sonu, saat dilimi) düşünülmüş mü? Güvenlik: Yetki kontrolü var mı? Kullanıcı girdisi doğrulanıyor mu? Tasarım: Değişiklik doğru katmanda mı? Var olan bir servis yeniden mi yazılmış? Test: Davranışı koruyan bir test eklenmiş mi? Okunabilirlik: İsimler anlaşılır mı? Gereksiz karmaşıklık var mı? Biçimlendirme ve stil konuları incelemede tartışılmaz; bunlar lint ve formatlayıcının işidir. Geri bildirim dili Yorumun önüne etiket koyarak niyetinizi netleştirin: Etiket Anlamı engel: Birleştirmeden önce düzeltilmeli öneri: Daha iyi olabilir, karar yazarın soru: Anlamadım, açıklar mısın? ufak: Önemsiz, istersen düzelt övgü: Bunu beğendim Kişiyi değil kodu eleştirin. "Burada hata yapmışsın" yerine "Bu satır liste boşken hata veriyor gibi" deyin. Süreler İnceleme isteğine bir iş günü içinde ilk yanıt verilir. Yazar, geri bildirimlere en geç bir iş günü içinde döner. Üç turdan uzun süren tartışmalar yazılı yazışma yerine 15 dakikalık bir görüşmeyle çözülür.', 2, 1, (SELECT id FROM users WHERE full_name = 'Ayşe Kaya' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Ayşe Kaya' ORDER BY id LIMIT 1), '2026-08-28 06:00:00', '2026-08-28 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('olay-yonetimi', 'Olay Yönetimi ve Nöbet', 'Üretimde bir sorun çıktığında önem seviyeleri, ilk müdahale adımları, iletişim ve olay sonrası rapor.', 'kalite', 'incident,nöbet,postmortem',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Üretimde bir şey ters gittiğinde amacımız önce etkiyi durdurmak, sonra nedenini bulmaktır. Suçlu aranmaz; süreç iyileştirilir."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Önem seviyeleri"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Seviye"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tanım"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"İlk yanıt"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Örnek"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"SEV1"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sistem tamamen erişilemez veya veri kaybı var"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"15 dk"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Veritabanı çöktü"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"SEV2"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Önemli bir özellik çalışmıyor, geçici çözüm yok"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"1 saat"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kimse giriş yapamıyor"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"SEV3"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Bir özellik kısmen bozuk, geçici çözüm var"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"1 iş günü"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rapor dışa aktarma hatalı"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"SEV4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kozmetik sorun"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Sonraki sprint"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Yanlış hizalanmış buton"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"İlk müdahale"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kabul edin:","marks":[{"type":"bold"}]},{"type":"text","text":" Nöbetçi, uyarıyı aldığını #olaylar kanalında bildirir."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Etkiyi ölçün:","marks":[{"type":"bold"}]},{"type":"text","text":" Sistem İzleme sayfasında hangi servislerin etkilendiğine bakın."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Durdurun:","marks":[{"type":"bold"}]},{"type":"text","text":" Son yayın sonrası başladıysa önce geri alın."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"İletişim kurun:","marks":[{"type":"bold"}]},{"type":"text","text":" SEV1 ve SEV2 için her 30 dakikada bir durum güncellemesi yazın."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kapatın:","marks":[{"type":"bold"}]},{"type":"text","text":" Etki bittiğinde olayı kapatın ve rapor için bir görev açın."}]}]}],"attrs":{"start":1}},{"type":"callout","attrs":{"kind":"ONEMLI"},"content":[{"type":"paragraph","content":[{"type":"text","text":"SEV1 durumunda nöbetçi tek başına çalışmaz. İlk 15 dakikada çözülemiyorsa takım liderini ve altyapı sorumlusunu çağırın."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"İlk bakılacak yerler"}]},{"type":"codeBlock","attrs":{"language":"bash"},"content":[{"type":"text","text":"# Servislerin durumu\\ndocker compose ps\\n\\n# Backend''in son logları\\ndocker compose logs --tail=200 backend\\n\\n# Veritabanı bağlantı sayısı\\ndocker exec devhub-mysql mysql -uroot -p -e \\"SHOW STATUS LIKE ''Threads_connected'';\\""}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Nöbet düzeni"}]},{"type":"paragraph","content":[{"type":"text","text":"Nöbet haftalıktır ve pazartesi 10:00''da devredilir. Nöbetçi mesai dışında 30 dakika içinde bilgisayar başında olabilmelidir. İzin planlanırken nöbet haftasına denk gelmemesine dikkat edilir; gerekirse takas yapılır."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Olay sonrası rapor"}]},{"type":"paragraph","content":[{"type":"text","text":"SEV1 ve SEV2 olayları için beş iş günü içinde rapor yazılır:"}]},{"type":"codeBlock","attrs":{"language":"text"},"content":[{"type":"text","text":"Başlık:        Giriş servisinde 40 dakikalık kesinti\\nTarih/Süre:    12.09.2026 14:10 – 14:50\\nEtki:          Kullanıcıların %100''ü giriş yapamadı\\nKök neden:     Süresi dolan JWT imzalama anahtarı\\nTespit:        Sistem İzleme uyarısı + kullanıcı bildirimi\\nNe iyi gitti:  Geri alma 6 dakikada tamamlandı\\nAksiyonlar:    [DH-201] Anahtar süresi için 14 gün önceden uyarı"}]},{"type":"callout","attrs":{"kind":"NOT"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Raporda kişi adı değil rol yazılır: \\"geliştirici yanlış komutu çalıştırdı\\" yerine \\"komut, üretim ortamını onay istemeden değiştirebiliyordu\\"."}]}]}]}',
        'Üretimde bir şey ters gittiğinde amacımız önce etkiyi durdurmak, sonra nedenini bulmaktır. Suçlu aranmaz; süreç iyileştirilir. Önem seviyeleri Seviye Tanım İlk yanıt Örnek SEV1 Sistem tamamen erişilemez veya veri kaybı var 15 dk Veritabanı çöktü SEV2 Önemli bir özellik çalışmıyor, geçici çözüm yok 1 saat Kimse giriş yapamıyor SEV3 Bir özellik kısmen bozuk, geçici çözüm var 1 iş günü Rapor dışa aktarma hatalı SEV4 Kozmetik sorun Sonraki sprint Yanlış hizalanmış buton İlk müdahale Kabul edin: Nöbetçi, uyarıyı aldığını #olaylar kanalında bildirir. Etkiyi ölçün: Sistem İzleme sayfasında hangi servislerin etkilendiğine bakın. Durdurun: Son yayın sonrası başladıysa önce geri alın. İletişim kurun: SEV1 ve SEV2 için her 30 dakikada bir durum güncellemesi yazın. Kapatın: Etki bittiğinde olayı kapatın ve rapor için bir görev açın. SEV1 durumunda nöbetçi tek başına çalışmaz. İlk 15 dakikada çözülemiyorsa takım liderini ve altyapı sorumlusunu çağırın. İlk bakılacak yerler # Servislerin durumu docker compose ps # Backend''in son logları docker compose logs --tail=200 backend # Veritabanı bağlantı sayısı docker exec devhub-mysql mysql -uroot -p -e "SHOW STATUS LIKE ''Threads_connected'';" Nöbet düzeni Nöbet haftalıktır ve pazartesi 10:00''da devredilir. Nöbetçi mesai dışında 30 dakika içinde bilgisayar başında olabilmelidir. İzin planlanırken nöbet haftasına denk gelmemesine dikkat edilir; gerekirse takas yapılır. Olay sonrası rapor SEV1 ve SEV2 olayları için beş iş günü içinde rapor yazılır: Başlık: Giriş servisinde 40 dakikalık kesinti Tarih/Süre: 12.09.2026 14:10 – 14:50 Etki: Kullanıcıların %100''ü giriş yapamadı Kök neden: Süresi dolan JWT imzalama anahtarı Tespit: Sistem İzleme uyarısı + kullanıcı bildirimi Ne iyi gitti: Geri alma 6 dakikada tamamlandı Aksiyonlar: [DH-201] Anahtar süresi için 14 gün önceden uyarı Raporda kişi adı değil rol yazılır: "geliştirici yanlış komutu çalıştırdı" yerine "komut, üretim ortamını onay istemeden değiştirebiliyordu".', 2, 1, (SELECT id FROM users WHERE full_name = 'Mustafa Koç' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Mustafa Koç' ORDER BY id LIMIT 1), '2026-09-19 06:00:00', '2026-09-19 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('sistem-mimarisi', 'Sistem Mimarisi', 'DevHub''ı oluşturan servisler, katmanlar, kimlik doğrulama akışı ve servisler arası iletişim.', 'mimari', 'mimari,backend,frontend',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DevHub; bir React tek sayfa uygulaması, bir Spring Boot REST API ve bir MySQL veritabanından oluşur. Tüm parçalar Docker konteynerlerinde çalışır."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Genel bakış"}]},{"type":"codeBlock","attrs":{"language":"text"},"content":[{"type":"text","text":" Tarayıcı ──HTTPS──▶ Web Arayüzü (React + Vite)\\n                         │  JSON / JWT\\n                         ▼\\n                    Backend API (Spring Boot 4, Java 21)\\n                         │  JDBC\\n                         ▼\\n                    MySQL 8 (Flyway ile yönetilen şema)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Servis"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Teknoloji"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Port"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Web arayüzü"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"React 19, TypeScript, Tailwind, React Query"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"5173"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Backend API"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content"