        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Her "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":" birleştirmesi otomatik olarak staging ortamına dağıtılır. Üretime yayın ise haftada iki kez, salı ve perşembe günleri yapılır."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sürüm numaraları"}]},{"type":"paragraph","content":[{"type":"text","text":"Semantic Versioning","marks":[{"type":"link","attrs":{"href":"https://semver.org"}}]},{"type":"text","text":" kullanıyoruz: "},{"type":"text","text":"MAJOR.MINOR.PATCH","marks":[{"type":"code"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Parça"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Artar"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Örnek"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"MAJOR"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Geriye dönük uyumsuz API değişikliği"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"2.0.0"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"MINOR"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Uyumlu yeni özellik"}]}]},{