origin v1.8.0"}]},{"type":"callout","attrs":{"kind":"ONEMLI"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cuma günleri ve resmî tatil öncesi son iş günü üretime yayın yapılmaz. Acil güvenlik düzeltmeleri bu kuralın tek istisnasıdır."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Veritabanı değişiklikleri"}]},{"type":"paragraph","content":[{"type":"text","text":"Şema değişiklikleri her zaman kodla aynı sürümde, Flyway migration''ı olarak gelir ve "},{"type":"text","text":"geriye dönük uyumlu","marks":[{"type":"bold"}]},{"type":"text","text":" olmalıdır. Bir kolonu silmek iki yayına yayılır:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yayın: Kod kolonu okumayı bırakır."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yayın: Migration kolonu siler."}]}]}],"attrs":{"start":1}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Geri alma"}]},{"type":"paragraph","content":[{"type":"text","text":"Yayından sonra hata oranı yükselirse önce geri alın, sonra araştırın:"}]},{"type":"codeBlock","attrs":{"language":"bash"},"content":[{"type":"text","text":"./deploy.sh rollback --to v1.7.3"}]},{"type":"callout","attrs":{"kind":"NOT"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Geri alma kararı için onay beklemeyin. Yayını yapan kişi bu yetkiye sahiptir; kararı sonra olay raporunda açıklar."}]}]}]}',
        'Her main birleştirmesi otomatik olarak staging ortamına dağıtılır. Üretime yayın ise haftada iki kez, salı ve perşembe günleri yapılır. Sürüm numaraları Semantic Versioning kullanıyoruz: MAJOR.MINOR.PATCH Parça Artar Örnek MAJOR Geriye dönük uyumsuz API değişikliği 2.0.0 MINOR Uyumlu yeni özellik 1.4.0 PATCH Uyumlu hata düzeltmesi 1.4.2 Sürüm numarası commit mesajlarından otomatik belirlenir: feat MINOR, fix PATCH, BREAKING CHANGE MAJOR artırır. Yayın adımları Staging''de duman testleri (smoke test) geçer. Sürüm etiketi oluşturulur ve sürüm notları otomatik üretilir. Üretime kademeli dağıtım başlar: önce %10, 15 dakika sonra %100. Yayını yapan kişi 30 dakika boyunca Sistem İzleme sayfasını takip eder. git tag -a v1.8.0 -m "v1.8.0" git push origin v1.8.0 Cuma günleri ve resmî tatil öncesi son iş günü üretime yayın yapılmaz. Acil güvenlik düzeltmeleri bu kuralın tek istisnasıdır. Veritabanı değişiklikleri Şema değişiklikleri her zaman kodla aynı sürümde, Flyway migration''ı olarak gelir ve geriye dönük uyumlu olmalıdır. Bir kolonu silmek iki yayına yayılır: Yayın: Kod kolonu okumayı bırakır. Yayın: Migration kolonu siler. Geri alma Yayından sonra hata oranı yükselirse önce geri alın, sonra araştırın: ./deploy.sh rollback --to v1.7.3 Geri alma kararı için onay beklemeyin. Yayını yapan kişi bu yetkiye sahiptir; kararı sonra olay raporunda açıklar.', 4, 1, (SELECT id FROM users WHERE full_name = 'Mustafa Koç' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Mustafa Koç' ORDER BY id LIMIT 1), '2026-09-05 06:00:00', '2026-09-05 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('test-stratejisi', 'Test Stratejisi', 'Test piramidi, birim ve entegrasyon testleri, test isimlendirme ve CI''da testlerin çalışması.', 'kalite', 'test,junit,kalite',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Testler hızlı geri bildirim için vardır. Bir değişikliğin bir şeyi bozup bozmadığını dakikalar içinde, üretimden önce öğrenmek isteriz."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Test piramidi"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Katman"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Oran"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ne test eder"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Araç"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Birim"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~%70"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tek bir sınıfın iş kuralı"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"JUnit 5, Mockito"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Entegrasyon"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~%25"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Controller → veritabanı akışı"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Spring Boot Test, Testcontainers"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Uçtan uca"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"~%5"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kritik kullanıcı akışları"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Playwright"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Neyi test ederiz?"}]},{"type":"paragraph","content":[{"type":"text","text":"İş kuralı içeren her servis metodu birim testine sahip olmalıdır. Özellikle:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"İzin günü hesabı: hafta sonu, resmî tatil, yıl dönümü"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Yetki kuralları: çalışan başkasının görevini değiştirememeli"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Durum geçişleri: izinli kişi kendi durumunu değiştirememeli"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Örnek birim testi"}]},{"type":"codeBlock","attrs":{"language":"java"},"content":[{"type":"text","text":"@Test\\nvoid haftaSonuVeResmiTatilIsGunuSayilmaz() {\\n    // 28 Ekim Çarşamba – 2 Kasım Pazartesi, 29 Ekim resmî tatil\\n    holidays.add(LocalDate.of(2026, 10, 29));\\n\\n    int days = workdayService.countWorkdays(\\n        LocalDate.of(2026, 10, 28), LocalDate.of(2026, 11, 2));\\n\\n    assertThat(days).isEqualTo(3); // Çar, Cum, Pzt\\n}"}]},{"type":"callout","attrs":{"kind":"IPUCU"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Test adları Türkçe ve cümle gibi yazılır; test başarısız olduğunda rapordaki ad, neyin bozulduğunu tek başına anlatmalıdır."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Entegrasyon testleri"}]},{"type":"paragraph","content":[{"type":"text","text":"Entegrasyon testleri gerçek bir MySQL ile çalışır. Testcontainers her test sınıfı için geçici bir veritabanı başlatır ve migration''ları uygular:"}]},{"type":"codeBlock","attrs":{"language":"java"},"content":[{"type":"text","text":"@SpringBootTest\\n@Testcontainers\\nclass LeaveControllerIT {\\n    @Container\\n    static MySQLContainer<?> mysql = new MySQLContainer<>(\\"mysql:8.0\\");\\n}"}]},{"type":"callout","attrs":{"kind":"UYARI"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Testler geliştiricinin yerel veritabanına bağlanmamalıdır. Yerel veriyi değiştiren bir test, bir sonraki sunumdan önce fark edilmeyen hatalara yol açar."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"CI''da testler"}]},{"type":"paragraph","content":[{"type":"text","text":"Her pull request''te sırasıyla şunlar çalışır ve biri başarısız olursa PR birleştirilemez:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"./gradlew test","marks":[{"type":"code"}]},{"type":"text","text":": backend birim ve entegrasyon testleri"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"npm run build","marks":[{"type":"code"}]},{"type":"text","text":": TypeScript kontrolü ve üretim derlemesi"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"npm run lint","marks":[{"type":"code"}]},{"type":"text","text":": oxlint kuralları"}]}]}],"attrs":{"start":1}}]}',
        'Testler hızlı geri bildirim için vardır. Bir değişikliğin bir şeyi bozup bozmadığını dakikalar içinde, üretimden önce öğrenmek isteriz. Test piramidi Katman Oran Ne test eder Araç Birim ~%70 Tek bir sınıfın iş kuralı JUnit 5, Mockito Entegrasyon ~%25 Controller → veritabanı akışı Spring Boot Test, Testcontainers Uçtan uca ~%5 Kritik kullanıcı akışları Playwright Neyi test ederiz? İş kuralı içeren her servis metodu birim testine sahip olmalıdır. Özellikle: İzin günü hesabı: hafta sonu, resmî tatil, yıl dönümü Yetki kuralları: çalışan başkasının görevini değiştirememeli Durum geçişleri: izinli kişi kendi durumunu değiştirememeli Örnek birim testi @Test void haftaSonuVeResmiTatilIsGunuSayilmaz() { // 28 Ekim Çarşamba – 2 Kasım Pazartesi, 29 Ekim resmî tatil holidays.add(LocalDate.of(2026, 10, 29)); int days = workdayService.countWorkdays( LocalDate.of(2026, 10, 28), LocalDate.of(2026, 11, 2)); assertThat(days).isEqualTo(3); // Çar, Cum, Pzt } Test adları Türkçe ve cümle gibi yazılır; test başarısız olduğunda rapordaki ad, neyin bozulduğunu tek başına anlatmalıdır. Entegrasyon testleri Entegrasyon testleri gerçek bir MySQL ile çalışır. Testcontainers her test sınıfı için geçici bir veritabanı başlatır ve migration''ları uygular: @SpringBootTest @Testcontainers class LeaveControllerIT { @Container static MySQLContainer<?> mysql = new MySQLContainer<>("mysql:8.0"); } Testler geliştiricinin yerel veritabanına bağlanmamalıdır. Yerel veriyi değiştiren bir test, bir sonraki sunumdan önce fark edilmeyen hatalara yol açar. CI''da testler Her pull request''te sırasıyla şunlar çalışır ve biri başarısız olursa PR birleştirilemez: ./gradlew test: backend birim ve entegrasyon testleri npm run build: TypeScript kontrolü ve üretim derlemesi npm run lint: oxlint kuralları', 1, 1, (SELECT id FROM users WHERE full_name = 'Zeynep Öztürk' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Zeynep Öztürk' ORDER BY id LIMIT 1), '2026-09-12 06:00:00', '2026-09-12 06:00:00');

INSERT INTO docs (slug, title, summary, category, tags, content, plain_text, sort_order, version, created_by_id, updated_by_id, created_at, updated_at)
VALUES ('veritabani-kurallari', 'Veritabanı ve Migration Kuralları', 'Flyway migration dosyaları, isimlendirme kuralları, indeksler ve güvenli şema değişikliği.', 'mimari', 'mysql,flyway,migration',
        '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Şema yalnızca Flyway migration''larıyla değişir. Hibernate şemayı oluşturmaz, yalnızca doğrular ("},{"type":"text","text":"ddl-auto=validate","marks":[{"type":"code"}]},{"type":"text","text":"). Entity''de yapılan her değişikliğin bir migration''ı olmalıdır; aksi hâlde uygulama açılmaz."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Migration dosyaları"}]},{"type":"codeBlock","attrs":{"language":"text"},"content":[{"type":"text","text":"src/main/resources/db/migration/\\n  V1__init.sql\\n  V2__add_projects_and_logs.sql\\n  ...\\n  V10__task_details.sql"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dosya adı "},{"type":"text","text":"V<numara>__<açıklama>.sql","marks":[{"type":"code"}]},{"type":"text","text":" biçimindedir; açıklama küçük harf ve alt çizgiyle yazılır."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Birleşmiş bir migration dosyası "},{"type":"text","text":"asla değiştirilmez","marks":[{"type":"bold"}]},{"type":"text","text":". Hata varsa yeni bir migration yazılır."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Her migration tek bir amaca hizmet eder ve dosyanın başında neden yazıldığı açıklanır."}]}]}]},{"type":"callout","attrs":{"kind":"UYARI"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Çalışmış bir migration''ı düzenlerseniz Flyway checksum hatası verir ve uygulama hiçbir ortamda açılmaz."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"İsimlendirme"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Öğe"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kural"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Örnek"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tablo"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"çoğul, snake_case"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"leave_requests","marks":[{"type":"code"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Kolon"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"snake_case"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"created_at","marks":[{"type":"code"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Yabancı anahtar"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"fk_<tablo>_<alan>","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"fk_task_project","marks":[{"type":"code"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"İndeks"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"idx_<tablo>_<alanlar>","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"idx_task_activity_task","marks":[{"type":"code"}]}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Benzersiz kısıt"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"uq_<tablo>_<alan>","marks":[{"type":"code"}]}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"uq_notification_ref","marks":[{"type":"code"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Örnek migration"}]},{"type":"codeBlock","attrs":{"language":"sql"},"content":[{"type":"text","text":"-- Görev yorumları ve geçmişi tek tabloda tutulur.\\nCREATE TABLE task_activity (\\n    id BIGINT AUTO_INCREMENT PRIMARY KEY,\\n    task_id BIGINT NOT NULL,\\n    actor_id BIGINT NULL,\\n    kind ENUM(''EVENT'', ''COMMENT'') NOT NULL,\\n    message VARCHAR(1000) NOT NULL,\\n    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\\n    CONSTRAINT fk_task_activity_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,\\n    INDEX idx_task_activity_task (task_id, created_at)\\n);"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Performans"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sık filtrelenen her kolon için indeks düşünülür; "},{"type":"text","text":"EXPLAIN","marks":[{"type":"code"}]},{"type":"text","text":" çıktısı PR açıklamasına eklenir."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Listelerde N+1 sorgusundan kaçınmak için ilişkiler "},{"type":"text","text":"@EntityGraph","marks":[{"type":"code"}]},{"type":"text","text":" ile tek sorguda çekilir."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"100.000 satırı geçebilecek tablolara yapılan "},{"type":"text","text":"ALTER","marks":[{"type":"code"}]},{"type":"text","text":" işlemleri önce staging''de süre ölçülerek denenir."}]}]}]},{"type":"callout","attrs":{"kind":"IPUCU"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Geliştirme sırasında "},{"type":"text","text":"spring.jpa.show-sql=true","marks":[{"type":"code"}]},{"type":"text","text":" ile Hibernate''in ürettiği sorguları görebilirsiniz; bir liste ekranı onlarca sorgu üretiyorsa N+1 vardır."}]}]}]}',
        'Şema yalnızca Flyway migration''larıyla değişir. Hibernate şemayı oluşturmaz, yalnızca doğrular (ddl-auto=validate). Entity''de yapılan her değişikliğin bir migration''ı olmalıdır; aksi hâlde uygulama açılmaz. Migration dosyaları src/main/resources/db/migration/ V1__init.sql V2__add_projects_and_logs.sql ... V10__task_details.sql Dosya adı V<numara>__<açıklama>.sql biçimindedir; açıklama küçük harf ve alt çizgiyle yazılır. Birleşmiş bir migration dosyası asla değiştirilmez. Hata varsa yeni bir migration yazılır. Her migration tek bir amaca hizmet eder ve dosyanın başında neden yazıldığı açıklanır. Çalışmış bir migration''ı düzenlerseniz Flyway checksum hatası verir ve uygulama hiçbir ortamda açılmaz. İsimlendirme Öğe Kural Örnek Tablo çoğul, snake_case leave_requests Kolon snake_case created_at Yabancı anahtar fk_<tablo>_<alan> fk_task_project İndeks idx_<tablo>_<alanlar> idx_task_activity_task Benzersiz kısıt uq_<tablo>_<alan> uq_notification_ref Örnek migration -- Görev yorumları ve geçmişi tek tabloda tutulur. CREATE TABLE task_activity ( id BIGINT AUTO_INCREMENT PRIMARY KEY, task_id BIGINT NOT NULL, actor_id BIGINT NULL, kind ENUM(''EVENT'', ''COMMENT'') NOT NULL, message VARCHAR(1000) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_task_activity_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE, INDEX idx_task_activity_task (task_id, created_at) ); Performans Sık filtrelenen her kolon için indeks düşünülür; EXPLAIN çıktısı PR açıklamasına eklenir. Listelerde N+1 sorgusundan kaçınmak için ilişkiler @EntityGraph ile tek sorguda çekilir. 100.000 satırı geçebilecek tablolara yapılan ALTER işlemleri önce staging''de süre ölçülerek denenir. Geliştirme sırasında spring.jpa.show-sql=true ile Hibernate''in ürettiği sorguları görebilirsiniz; bir liste ekranı onlarca sorgu üretiyorsa N+1 vardır.', 3, 1, (SELECT id FROM users WHERE full_name = 'Merve Can' ORDER BY id LIMIT 1), (SELECT id FROM users WHERE full_name = 'Merve Can' ORDER BY id LIMIT 1), '2026-08-22 06:00:00', '2026-08-22 06:00:00');

